import { createContext, useContext, type HTMLAttributes } from "react";
import type { ItemInstance, TreeInstance } from "@headless-tree/core";
import { ChevronDown, ChevronRight, Minus, Plus } from "lucide-react";
import { cn } from "@/ui/utils";
import { selectOnClick } from "./tree-select";

type TreeContextValue<T> = {
  indent: number;
  tree?: TreeInstance<T>;
  toggleIconType: "chevron" | "plus-minus";
  currentItem?: ItemInstance<T>;
};

const TreeContext = createContext<TreeContextValue<any>>({
  indent: 12,
  toggleIconType: "chevron",
});

function useTreeContext<T>() {
  return useContext(TreeContext) as TreeContextValue<T>;
}

export type TreeProps<T> = HTMLAttributes<HTMLDivElement> & {
  tree: TreeInstance<T>;
  indent?: number;
  toggleIconType?: "chevron" | "plus-minus";
};

export function Tree<T>({
  tree,
  indent = 12,
  toggleIconType = "chevron",
  className,
  children,
  onKeyDown,
  ...props
}: TreeProps<T>) {
  const containerProps = tree.getContainerProps() as Record<string, unknown> & {
    ref?: (el: HTMLDivElement | null) => void;
  };
  const { ref: registerTree, ...containerRest } = containerProps;

  return (
    <TreeContext.Provider value={{ indent, tree, toggleIconType }}>
      <div
        ref={registerTree}
        className={cn("relative flex flex-col", className)}
        {...containerRest}
        {...props}
        onKeyDownCapture={onKeyDown}
      >
        {children}
        <TreeDragLine />
      </div>
    </TreeContext.Provider>
  );
}

export type TreeItemProps<T> = HTMLAttributes<HTMLDivElement> & {
  item: ItemInstance<T>;
  indent?: number;
};

export function TreeItem<T>({
  item,
  indent,
  className,
  children,
  onClick,
  ...props
}: TreeItemProps<T>) {
  const ctx = useTreeContext<T>();
  const level = item.getItemMeta().level;
  const pad = (indent ?? ctx.indent) * level + 8;
  const { onClick: _defaultClick, ...itemProps } = item.getProps();

  return (
    <TreeContext.Provider value={{ ...ctx, currentItem: item }}>
      <div
        {...itemProps}
        {...props}
        style={{ paddingLeft: pad, ...(props.style ?? {}) }}
        onClick={(e) => {
          onClick?.(e);
          if (e.defaultPrevented) return;
          // Ignore bubbled clicks — label/chevron/drag handle handle their own.
          if (e.target !== e.currentTarget) return;
          selectOnClick(item, e);
          item.setFocused();
          item.getTree().updateDomFocus();
          item.primaryAction();
        }}
        className={cn(
          "group flex min-h-8 items-stretch gap-0.5 rounded-md pr-1 text-sm outline-none",
          item.isSelected() && "bg-secondary",
          // Nest-into-folder only — ordered drops use TreeDragLine, not row fill/opacity.
          item.isUnorderedDragTarget() &&
            item.isFolder() &&
            "bg-signal/5 ring-1 ring-inset ring-signal/30",
          className,
        )}
      >
        {children}
      </div>
    </TreeContext.Provider>
  );
}

export type TreeItemLabelProps<T> = HTMLAttributes<HTMLButtonElement> & {
  item?: ItemInstance<T>;
};

export function TreeItemLabel<T>({
  item,
  className,
  children,
  onClick,
  ...props
}: TreeItemLabelProps<T>) {
  const ctx = useTreeContext<T>();
  const node = item ?? ctx.currentItem;
  if (!node) return null;

  const { toggleIconType } = ctx;
  const folder = node.isFolder();

  return (
    <button
      type="button"
      tabIndex={-1}
      className={cn(
        "flex min-h-8 min-w-0 flex-1 items-center gap-2 self-stretch text-left",
        className,
      )}
      onClick={(e) => {
        e.stopPropagation();
        node.setFocused();
        node.getTree().updateDomFocus();
        onClick?.(e);
        if (e.defaultPrevented) return;
        selectOnClick(node, e);
        node.primaryAction();
      }}
      {...props}
    >
      <span
        data-tree-toggle=""
        className="grid size-6 shrink-0 place-items-center text-muted-foreground"
        onClick={(e) => {
          if (!folder) return;
          e.stopPropagation();
          if (node.isExpanded()) node.collapse();
          else node.expand();
        }}
      >
        {!folder ? (
          <span className="size-3.5" />
        ) : toggleIconType === "plus-minus" ? (
          node.isExpanded() ? (
            <Minus className="size-3.5" />
          ) : (
            <Plus className="size-3.5" />
          )
        ) : node.isExpanded() ? (
          <ChevronDown className="size-3.5" />
        ) : (
          <ChevronRight className="size-3.5" />
        )}
      </span>
      {children ?? <span className="truncate">{node.getItemName()}</span>}
    </button>
  );
}

export function TreeDragLine({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  const { tree } = useTreeContext();
  if (!tree || typeof tree.getDragLineStyle !== "function") return null;
  const style = tree.getDragLineStyle();
  if (!style || style.display === "none") return null;

  return (
    <div
      {...props}
      style={style}
      className={cn("pointer-events-none z-20 h-0.5 bg-signal", className)}
    />
  );
}

export function TreeDragHandle<T>({
  item,
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement> & { item: ItemInstance<T> }) {
  return (
    <span
      {...item.getDragHandleProps()}
      className={cn(
        "grid size-6 shrink-0 cursor-grab touch-none place-items-center text-muted-foreground opacity-40 transition-opacity hover:opacity-100 active:cursor-grabbing group-hover:opacity-100",
        className,
      )}
      {...props}
    />
  );
}

export type { ItemInstance, TreeInstance };

import type { FeatureImplementation } from "@headless-tree/core";

/**
 * Replaces headless-tree's `updateDomFocus`, which calls `element.focus()`
 * without `preventScroll` (the browser then scrolls the row on its own, outside
 * the app's reveal logic) and, if the row is not mounted within 500 ms, moves
 * focus to the first row — jumping the list to the top. Register it last.
 */
export const preventScrollFocusFeature: FeatureImplementation = {
  key: "prevent-scroll-focus",
  treeInstance: {
    updateDomFocus: ({ tree }) => {
      requestAnimationFrame(() => {
        tree.getFocusedItem()?.getElement()?.focus({ preventScroll: true });
      });
    },
  },
};

import type { ItemInstance } from "@headless-tree/core";

type ClickModifiers = { shiftKey: boolean; ctrlKey: boolean; metaKey: boolean };

/**
 * The selection half of headless-tree's row click, without the folder toggle that comes with
 * it (the rows open and close from the chevron only). A click selects the row, Ctrl or Cmd
 * adds or removes it, and Shift selects the range from the last row clicked. Does nothing
 * when the tree has no selection feature.
 */
export function selectOnClick<T>(item: ItemInstance<T>, e: ClickModifiers): void {
  if (typeof item.toggleSelect !== "function") return;
  const tree = item.getTree();
  const additive = e.ctrlKey || e.metaKey;
  if (e.shiftKey) item.selectUpTo(additive);
  else if (additive) item.toggleSelect();
  else tree.setSelectedItems([item.getId()]);
  // The anchor a later Shift-click ranges from, kept where headless-tree keeps it.
  if (!e.shiftKey) {
    tree.getDataRef<{ selectUpToAnchorId?: string | null }>().current.selectUpToAnchorId =
      item.getId();
  }
}

import { createTree, type TreeInstance } from "@headless-tree/core";
import { expect, it } from "vitest";
import { buildTreeConfig, TREE_ROOT } from "@/ui/tree-controller";
import { selectOnClick } from "./tree-select";

type Node = { id: string; parentId: string | null; folder: boolean };

const nodes: Node[] = [
  { id: TREE_ROOT, parentId: null, folder: true },
  { id: "a", parentId: TREE_ROOT, folder: true },
  { id: "b", parentId: TREE_ROOT, folder: false },
  { id: "c", parentId: TREE_ROOT, folder: false },
  { id: "d", parentId: TREE_ROOT, folder: false },
];

const plain = { shiftKey: false, ctrlKey: false, metaKey: false };
const ctrl = { ...plain, ctrlKey: true };
const shift = { ...plain, shiftKey: true };

function mount(selectable = true): TreeInstance<Node> {
  const tree = createTree(
    buildTreeConfig({
      items: nodes,
      getId: (node) => node.id,
      getParentId: (node) => node.parentId,
      getItemName: (node) => node.id,
      isFolder: (node) => node.folder,
      selectable,
    }),
  );
  tree.setMounted(true);
  tree.rebuildTree();
  return tree;
}

const selected = (tree: TreeInstance<Node>) => tree.getState().selectedItems ?? [];

it("selects the clicked row alone", () => {
  const tree = mount();
  selectOnClick(tree.getItemInstance("b"), plain);
  selectOnClick(tree.getItemInstance("c"), plain);
  expect(selected(tree)).toEqual(["c"]);
});

it("adds and removes a row with Ctrl", () => {
  const tree = mount();
  selectOnClick(tree.getItemInstance("b"), plain);
  selectOnClick(tree.getItemInstance("d"), ctrl);
  expect(selected(tree)).toEqual(["b", "d"]);
  selectOnClick(tree.getItemInstance("b"), ctrl);
  expect(selected(tree)).toEqual(["d"]);
});

it("selects the range from the last clicked row with Shift", () => {
  const tree = mount();
  selectOnClick(tree.getItemInstance("b"), plain);
  selectOnClick(tree.getItemInstance("d"), shift);
  expect([...selected(tree)].sort()).toEqual(["b", "c", "d"]);
});

it("leaves a folder closed: selecting is not opening", () => {
  const tree = mount();
  selectOnClick(tree.getItemInstance("a"), plain);
  expect(selected(tree)).toEqual(["a"]);
  expect(tree.getItemInstance("a").isExpanded()).toBe(false);
});

it("does nothing on a tree without selection", () => {
  const tree = mount(false);
  expect(() => selectOnClick(tree.getItemInstance("b"), plain)).not.toThrow();
});

import {
  dragAndDropFeature,
  hotkeysCoreFeature,
  selectionFeature,
  syncDataLoaderFeature,
  type FeatureImplementation,
  type TreeConfig,
  type TreeInstance,
} from "@headless-tree/core";
import { useTree } from "@headless-tree/react";
import { preventScrollFocusFeature } from "@/ui/primitives/tree-focus";

/** The id the root of a tree is expected to carry when it is not passed explicitly. */
export const TREE_ROOT = "__root__";

/** What every tree needs to know about an item: its id, and its parent's id. */
export type TreeIdentity<T> = {
  getId: (item: T) => string;
  /** The parent id, or null/undefined for an item at the top level. */
  getParentId: (item: T) => string | null | undefined;
};

/** How to read an item: its identity, its label, and whether it can hold children. */
export type TreeAccessors<T> = TreeIdentity<T> & {
  getItemName: (item: T) => string;
  /** Defaults to "it has children", read from the items themselves. */
  isFolder?: (item: T) => boolean;
};

/** The synchronous loader a flat list is read through. */
export type TreeLoader<T> = {
  getItem: (itemId: string) => T;
  getChildren: (itemId: string) => string[];
};

/** A flat list, ready for headless-tree: the resolved root, its loader, and a child test. */
export type TreeIndex<T> = {
  rootId: string;
  dataLoader: TreeLoader<T>;
  hasChildren: (itemId: string) => boolean;
};

/**
 * Which item is the root. An explicit id wins, and has to be one of the items; otherwise
 * the single item with no parent is the root, and an ambiguous list is an error rather
 * than a guess. An item whose parent is missing is not a root: it is shown at the root.
 */
export function resolveRootId<T>(
  items: T[],
  { getId, getParentId }: TreeIdentity<T>,
  rootId?: string,
): string {
  const ids = new Set(items.map(getId));
  if (rootId !== undefined) {
    if (!ids.has(rootId)) throw new Error(`Tree root "${rootId}" is not one of the items.`);
    return rootId;
  }
  const top = items
    .filter((item) => {
      const parent = getParentId(item);
      return parent === null || parent === undefined;
    })
    .map(getId);
  if (top.length === 1) return top[0];
  throw new Error(
    top.length === 0
      ? "No tree item is at the top level; name one with rootId."
      : `Several tree items are at the top level (${top.join(", ")}); name one with rootId.`,
  );
}

/**
 * Turns a flat list into headless-tree's `dataLoader`, with the root resolved. Items keep
 * the order they were given in, within their parent. An item whose parent is missing is
 * shown at the root, as is the root itself — it is never its own child.
 */
export function createTreeIndex<T>(
  items: T[],
  accessors: TreeIdentity<T> & { rootId?: string },
): TreeIndex<T> {
  const { getId, getParentId } = accessors;
  const byId = new Map<string, T>();
  for (const item of items) byId.set(getId(item), item);

  const rootId = resolveRootId(items, accessors, accessors.rootId);
  const children = new Map<string, string[]>();
  for (const item of items) {
    const id = getId(item);
    if (id === rootId) continue;
    const parent = getParentId(item);
    const key = parent === null || parent === undefined || !byId.has(parent) ? rootId : parent;
    const bucket = children.get(key);
    if (bucket) bucket.push(id);
    else children.set(key, [id]);
  }

  return {
    rootId,
    hasChildren: (itemId) => (children.get(itemId)?.length ?? 0) > 0,
    dataLoader: {
      getItem: (itemId) => {
        const item = byId.get(itemId);
        if (item === undefined) throw new Error(`No tree item with id "${itemId}".`);
        return item;
      },
      getChildren: (itemId) => children.get(itemId) ?? [],
    },
  };
}

/** Expansion and keyboard, selection and drag-and-drop on request, the focus fix last. */
export function treeFeatures<T = unknown>({
  selectable,
  draggable,
}: { selectable?: boolean; draggable?: boolean } = {}): FeatureImplementation<T>[] {
  return [
    syncDataLoaderFeature,
    hotkeysCoreFeature,
    ...(selectable ? [selectionFeature] : []),
    ...(draggable ? [dragAndDropFeature] : []),
    // Last: the other features never touch updateDomFocus, but it means to be last.
    preventScrollFocusFeature,
  ];
}

export type TreeControllerOptions<T> = TreeAccessors<T> & {
  /** The flat list. One item is the root: name it with rootId, or leave one with no parent. */
  items: T[];
  rootId?: string;
  indent?: number;
  /** Selection on and off. Off by default: a plain tree needs no selection. */
  selectable?: boolean;
  /** Drag-and-drop on and off. Off by default. */
  draggable?: boolean;
  /** Replaces the default features entirely. */
  features?: FeatureImplementation<T>[];
  /** Anything else headless-tree takes, used as passed. */
  tree?: Omit<
    TreeConfig<T>,
    "rootItemId" | "dataLoader" | "getItemName" | "isItemFolder" | "features"
  >;
};

/**
 * The headless-tree config for a flat list: the loader built, the root resolved, the label
 * and folder test read off the item, and the usual features set. Pure, so it can be built
 * and driven without React.
 */
export function buildTreeConfig<T>({
  items,
  getId,
  getParentId,
  getItemName,
  isFolder,
  rootId,
  indent = 12,
  selectable,
  draggable,
  features,
  tree,
}: TreeControllerOptions<T>): TreeConfig<T> {
  const index = createTreeIndex(items, { getId, getParentId, rootId });
  return {
    indent,
    ...tree,
    rootItemId: index.rootId,
    getItemName: (item) => getItemName(item.getItemData()),
    isItemFolder: (item) =>
      isFolder ? isFolder(item.getItemData()) : index.hasChildren(item.getId()),
    dataLoader: index.dataLoader,
    features: features ?? treeFeatures<T>({ selectable, draggable }),
  };
}

/**
 * The whole of a tree's wiring, in one call: the flat list in, a headless-tree instance
 * out. Render it with the `Tree` and `TreeItem` primitives, and own only the data and the
 * actions. A structural change to the items needs `tree.rebuildTree()`: the tree reads
 * through the loader, and a new loader alone does not make it re-read.
 */
export function useTreeController<T>(options: TreeControllerOptions<T>): TreeInstance<T> {
  return useTree<T>(buildTreeConfig(options));
}

import { createTree, type TreeInstance } from "@headless-tree/core";
import { expect, it } from "vitest";
import {
  buildTreeConfig,
  createTreeIndex,
  resolveRootId,
  TREE_ROOT,
  treeFeatures,
  type TreeControllerOptions,
} from "./tree-controller";

type Node = { id: string; parentId: string | null; name: string; folder: boolean };

const getId = (node: Node) => node.id;
const getParentId = (node: Node) => node.parentId;
const getItemName = (node: Node) => node.name;
const isFolder = (node: Node) => node.folder;

const tree: Node[] = [
  { id: TREE_ROOT, parentId: null, name: "All", folder: true },
  { id: "a", parentId: TREE_ROOT, name: "A", folder: true },
  { id: "a1", parentId: "a", name: "A1", folder: false },
  { id: "a2", parentId: "a", name: "A2", folder: false },
  { id: "b", parentId: TREE_ROOT, name: "B", folder: false },
];

it("takes the one top-level item as the root when it is not named", () => {
  expect(resolveRootId(tree, { getId, getParentId })).toBe(TREE_ROOT);
});

it("takes a named root, and refuses one that is not an item", () => {
  expect(resolveRootId(tree, { getId, getParentId }, "a")).toBe("a");
  expect(() => resolveRootId(tree, { getId, getParentId }, "nope")).toThrow(/not one of the items/);
});

it("refuses to guess a root when the top level is empty or crowded", () => {
  expect(() => resolveRootId([], { getId, getParentId })).toThrow(/No tree item is at the top/);
  const two: Node[] = [
    { id: "x", parentId: null, name: "X", folder: false },
    { id: "y", parentId: null, name: "Y", folder: false },
  ];
  expect(() => resolveRootId(two, { getId, getParentId })).toThrow(
    /Several tree items are at the top/,
  );
});

it("groups the items under their parent, in the order they were given", () => {
  const { dataLoader, hasChildren, rootId } = createTreeIndex(tree, { getId, getParentId });
  expect(rootId).toBe(TREE_ROOT);
  expect(dataLoader.getChildren(TREE_ROOT)).toEqual(["a", "b"]);
  expect(dataLoader.getChildren("a")).toEqual(["a1", "a2"]);
  expect(dataLoader.getChildren("a1")).toEqual([]);
  expect(hasChildren("a")).toBe(true);
  expect(hasChildren("a1")).toBe(false);
  expect(hasChildren(TREE_ROOT)).toBe(true);
});

it("returns the item for an id, and throws for one it does not have", () => {
  const { dataLoader } = createTreeIndex(tree, { getId, getParentId });
  expect(dataLoader.getItem("a1")).toBe(tree[2]);
  expect(() => dataLoader.getItem("gone")).toThrow(/No tree item with id "gone"/);
});

it("shows an item whose parent is missing at the root, and never the root as its own child", () => {
  const orphan: Node[] = [
    { id: TREE_ROOT, parentId: null, name: "All", folder: true },
    { id: "kept", parentId: "deleted", name: "Kept", folder: false },
  ];
  const { dataLoader } = createTreeIndex(orphan, { getId, getParentId });
  expect(dataLoader.getChildren(TREE_ROOT)).toEqual(["kept"]);
  expect(dataLoader.getChildren(TREE_ROOT)).not.toContain(TREE_ROOT);
});

/** The config built the way the hook builds it, driven by the engine with no React. */
function mount(options: Partial<TreeControllerOptions<Node>> = {}): TreeInstance<Node> {
  const mounted = createTree(
    buildTreeConfig({ items: tree, getId, getParentId, getItemName, isFolder, ...options }),
  );
  mounted.setMounted(true);
  mounted.rebuildTree();
  return mounted;
}

it("reads the rows, folders and labels of a real tree off the flat list", () => {
  const mounted = mount();
  // Only the top level is shown until a folder opens.
  expect(mounted.getItems().map((item) => item.getId())).toEqual(["a", "b"]);
  expect(
    mounted
      .getItemInstance(TREE_ROOT)
      .getChildren()
      .map((item) => item.getId()),
  ).toEqual(["a", "b"]);
  expect(mounted.getItemInstance("a").isFolder()).toBe(true);
  expect(mounted.getItemInstance("a").getItemName()).toBe("A");

  mounted.getItemInstance("a").expand();
  expect(mounted.getItems().map((item) => item.getId())).toEqual(["a", "a1", "a2", "b"]);
  expect(
    mounted
      .getItemInstance("a")
      .getChildren()
      .map((item) => item.getId()),
  ).toEqual(["a1", "a2"]);
  expect(mounted.getItemInstance("a1").isFolder()).toBe(false);
});

it("opens and closes a folder", () => {
  const mounted = mount();
  const folder = mounted.getItemInstance("a");
  expect(folder.isExpanded()).toBe(false);
  folder.expand();
  expect(folder.isExpanded()).toBe(true);
  folder.collapse();
  expect(folder.isExpanded()).toBe(false);
});

it("leaves selection and drag-and-drop off unless they are asked for", () => {
  const plain = mount();
  expect(typeof plain.getItemInstance("a").isSelected).not.toBe("function");
  expect(typeof plain.getItemInstance("a").getDragHandleProps).not.toBe("function");

  const rich = mount({ selectable: true, draggable: true });
  expect(typeof rich.getItemInstance("a").isSelected).toBe("function");
  expect(typeof rich.getItemInstance("a").getDragHandleProps).toBe("function");
  rich.getItemInstance("a").select();
  expect(rich.getState().selectedItems ?? []).toContain("a");
});

it("ends the feature list with the focus fix, whichever features are on", () => {
  expect(
    treeFeatures()
      .map((feature) => feature.key)
      .at(-1),
  ).toBe("prevent-scroll-focus");
  expect(treeFeatures({ selectable: true, draggable: true }).at(-1)).toBe(treeFeatures().at(-1));
});
